// Read text output from Analyze Image
const raw =  $input.first().json['0'].content[0].text|| "";

// --- 1. Normalize ---
let text = raw
  .replace(/^text:\s*/i, "")   // remove "text:" prefix if present
  .trim();

// Split into lines and clean them
let lines = text
  .split(/\r?\n/)
  .map(l => l.trim())
  .filter(l => l.length > 0);

// --- 2. Find only item lines (“- Tomato - 1 kg”) ---
const itemLines = lines.filter(l =>
  /^[-•*]?\s*[A-Za-z].*-\s*\d/.test(l)   // something like "* Tomato - 1 kg"
);

// --- 3. Parse lines cleanly ---
function parseLine(line) {
  // Remove bullet symbols like "-", "•", "*"
  line = line.replace(/^[-•*]\s*/, "").trim();

  // Split on the LAST dash (so names with dashes still work)
  const idx = line.lastIndexOf(" - ");
  if (idx === -1) return null;

  const name = line.slice(0, idx).trim();
  const qty = line.slice(idx + 3).trim(); // after " - "

  return { name, qty };
}

// --- 4. Build key-value map ---
const mapped = {};

for (const line of itemLines) {
  const parsed = parseLine(line);
  if (!parsed) continue;

  const { name, qty } = parsed;

  // Clean quantity (normalize spacing)
  const cleanQty = qty.replace(/\s+/g, " ").trim();

  mapped[name] = cleanQty;
}

// --- 5. Return final object ---
return [
  {
    json: {
      mapped
    }
  }
];
